 const S=window.PERSIAN_SEMANTICS||(window.PERSIAN_SEMANTICS={});
 const semanticIndex=new Map(Object.entries(S).map(([k,v])=>[norm(k),v]));
 const finalByGroup=new Map();
 for(const [headword,refs] of clusterFinals) finalByGroup.set(headword,refs.filter(x=>!removed.has(x)));
 for(const [headword,refs] of finalByGroup){
  if(refs.length<2) continue;
  const labels=senseLabels[headword]||[];
  refs.forEach((item,index)=>{
   const display=labels[index]||headword+" ("+(item.pos||("sense "+(index+1)))+")";
   const meaning=(senseMeanings[headword]||[])[index];
   const original=item.fa;
   item.fa=display;
   if(meaning){
    const base=S[original]||semanticIndex.get(norm(original))||{};
    S[display]={...base,faMeaning:meaning[0],enMeaning:meaning[1],arMeaning:meaning[2],contextNote:"This entry is kept separately because it represents a distinct sense or grammatical use."};
   }
  });
 }
 for(const item of D){
  if(!S[item.fa]){
   const base=S[item._term03OriginalFa]||semanticIndex.get(norm(item._term03OriginalFa));
   if(base) S[item.fa]={...base};
  }
 }
 const retained=D.filter(x=>!removed.has(x));
 D.splice(0,D.length,...retained);
 const usedIds=new Set();
 for(const item of D){
  const originalFa=item._term03OriginalFa||item.fa;
  const base="3|"+item.unit+"|"+item.source+"|"+originalFa;
  let candidate=base;
  if(usedIds.has(candidate)){
   const label=String(item.fa).replace(/[()\s]+/g,"-").replace(/^-|-$/g,"");
   candidate=base+"|sense-"+label;
   let n=2;while(usedIds.has(candidate)) candidate=base+"|sense-"+label+"-"+(n++);
  }
  usedIds.add(candidate);
  item.id=candidate;
 }
 const idTargets=new Map();
 for(const item of D){
  for(const legacy of item._term03LegacyIds||[oldId(item)]){
   if(!idTargets.has(legacy)) idTargets.set(legacy,new Set());
   idTargets.get(legacy).add(item.id);
  }
 }
 let progressMigrated=false;
 try{
  const marker="term03_dedup_migration_v1";
  if(localStorage.getItem(marker)!=="1"){
   const done=new Set(JSON.parse(localStorage.getItem("persian_done_v1")||"[]"));
   const live=new Set(D.map(x=>x.id));
   for(const [legacy,targets] of idTargets){
    if(!done.has(legacy)) continue;
    for(const target of targets) if(!done.has(target)){done.add(target);progressMigrated=true;}
    if(!live.has(legacy)) done.delete(legacy);
   }
   if(progressMigrated) localStorage.setItem("persian_done_v1",JSON.stringify([...done]));
   localStorage.setItem(marker,"1");
  }
 }catch(error){console.warn("Term 03 memorisation migration could not be saved",error);}
 const ids=D.map(x=>x.id);
 const duplicateIds=ids.filter((id,index)=>ids.indexOf(id)!==index);
